 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, vec3, mix, color, fract, sin, dot, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const visual = config.intent?.visualSpec ?? config;
  const colors = visual?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;

      const texColor = texture(tex, uv());
      const grainUv = uv().mul(1024.0);
      const noise = fract(
        sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453)
      );
      const grain = add(texColor.rgb, vec3(noise).mul(0.035));

      material.map = tex;
      material.colorNode = mix(texColor.rgb, grain, 0.28);
      material.needsUpdate = true;
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (ctx.primitives?.[primitive.name]) {
      const p = ctx.primitives[primitive.name](group, primitive.params ?? {});
      if (p?.cleanup) {
        const existing = group.userData._primitiveCleanups ?? [];
        existing.push(p.cleanup);
        group.userData._primitiveCleanups = existing;
      }
    }
  }

  group.scale.set(0, 0, 0);

  const entrance = gsap.timeline({ defaults: { ease: 'power3.out' } });
  entrance.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.7, ease: 'back.out(1.3)' });
  entrance.to(material, { opacity: 1, duration: 0.6 }, 0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    entrance.kill();
    if (group.userData._primitiveCleanups) {
      for (const cleanup of group.userData._primitiveCleanups) {
        cleanup();
      }
    }
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
